const agentOutput = $input.first().json;
const replyText = agentOutput.output ?? '';
const steps = agentOutput.intermediateSteps ?? [];

let button = null;

for (const step of steps) {
  const toolName = step.action?.tool;
  if (toolName !== 'propose_coupon') continue;

  let observation = step.observation;

  // Workflow Tool observations come back in n8n's standard items shape:
  // an array of { json: {...} } (or, seen in practice, an array of the
  // raw json objects directly) - unwrap either form to a plain object.
  // They can also arrive as a JSON-stringified array (known n8n Call
  // Workflow Tool quirk) - parse it first if so.
  if (typeof observation === 'string') {
    try {
      observation = JSON.parse(observation);
    } catch (e) {
      continue;
    }
  }

  if (Array.isArray(observation)) {
    const first = observation[0];
    observation = first?.json ?? first ?? {};
  }

  if (observation?.status !== 'proposed') continue;

  const toolInput = step.action.toolInput ?? {};
  const categoryId = toolInput.category_id;
  const discountPercent = toolInput.discount_percent;

  // expires_days is optional on the model's side - if the model didn't
  // pass it, 13a-tool-propose-coupon applies its own default and reflects
  // the resulting date in observation.payload.date_expires. Derive the
  // days-from-now from that actual date instead of requiring the model to
  // echo a value it had no reason to set.
  let expiresDays = toolInput.expires_days;
  if (expiresDays === undefined) {
    const expiresDate = observation?.payload?.date_expires;
    if (expiresDate) {
      const DateTime = $now.constructor;
      const diffDays = DateTime.fromISO(expiresDate).diff($today, 'days').days;
      expiresDays = Math.round(diffDays);
    }
  }

  if (categoryId === undefined || discountPercent === undefined || expiresDays === undefined) {
    continue;
  }

  const categoryName = observation.category?.name ?? `category ${categoryId}`;

  button = {
    label: `✅ Confirm ${discountPercent}% off ${categoryName}`,
    callback_data: `cc:${categoryId}:${discountPercent}:${expiresDays}`,
  };
}

return [{
  json: {
    reply_text: replyText,
    button,
  },
}];
